//! Release-derived `D_Quests` class checksums and pure `AQuest::Check` rules
//! (`F-935`, `U-074`, derived offline from official 3.0.31 / 3.0.32 dedicated
//! server paks with zero release drift across all 2,044 quest classes).

/// Base `AQuest` (`4_033_596_864` / `0xf06bb060`) network class checksum.
pub const AQUEST_CLASS_CHECKSUM: u32 = 4_033_596_864;

/// Pure completion rule compiled from a quest class's cooked `Check()` graph.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum QuestCheckRule {
    /// Native `AQuest::Check_Implementation` or constant `false`.
    AlwaysFalse,
    /// Constant `true`.
    AlwaysTrue,
    /// `GetBooleanVariable(name)`.
    BoolVar(&'static str),
    /// `GetBooleanVariable(name)` when `false`; `true` runs `ManualRunOperation(s)` (CDO `AllowChecksAfterCompletion == true`).
    BoolVarFalseOnly(&'static str),
    /// `GetQuestFlag(flag)` against `C015` `SessionFlags`.
    QuestFlag(&'static str),
    /// Conjunction of `GetBooleanVariable` lookups.
    AllBoolVars(&'static [&'static str]),
    /// Disjunction of `GetBooleanVariable` lookups.
    AnyBoolVars(&'static [&'static str]),
    /// Disjunction of `GetQuestFlag` lookups.
    AnyQuestFlags(&'static [&'static str]),
    /// `GetBooleanVariable(var) || GetQuestFlag(flag)`.
    BoolVarOrQuestFlag(&'static str, &'static str),
    /// `GetIntVariable(var) >= min`.
    IntVarAtLeast(&'static str, i32),
    /// `GetIntVariable(lhs) >= GetIntVariable(rhs)`.
    IntVarAtLeastVar(&'static str, &'static str),
    /// `GetIntVariable(var) <= max`.
    IntVarAtMost(&'static str, i32),
    /// `GetFloatVariable(lhs) >= GetFloatVariable(rhs)`.
    FloatVarAtLeastVar(&'static str, &'static str),
    /// `GetFloatVariable(var) > bound`.
    FloatVarGreater(&'static str, f32),
    /// Reads world state, CDO/instance properties, or mutating helpers; fails closed.
    Impure,
}

/// Derived replication checksum, `CPF_Net` extension flag, and `Check()` rule
/// for one `D_Quests` quest class.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct QuestClassSpec {
    pub class_name: &'static str,
    pub checksum: u32,
    pub adds_net_props: bool,
    pub check: QuestCheckRule,
}

